krpano.action:
tween(scale, 0.8, 0.8, easeInOutSine,
	tween(scale, 0.8, 0.8, easeInOutSine, hotspot_breathe() )
);

if(caller.linkedscene,
	copy(hs_linkedscene, caller.linkedscene);
	if(caller.linkedscene_lookat, txtsplit(caller.linkedscene_lookat, ',', hs_lookat_h, hs_lookat_v, hs_lookat_fov); );
	set(caller.enabled, false);
	skin_hidetooltips();
	hide_custom_tooltip();

	tween(caller.oy|caller.alpha|caller.rx, -50|0.0|90, 0.5, easeOutQuad,
		skin_loadscene(get(hs_linkedscene), get(skin_settings.loadscene_blend));
		if(hs_lookat_h !== null, skin_lookat(get(hs_lookat_h), get(hs_lookat_v), get(hs_lookat_fov)); );
		skin_updatescroll();
	);
);

if(hotspot[%1].loaded,
	inc(hotspot[%1].myframe);
	if(hotspot[%1].myframe GT 23, set(hotspot[%1].myframe, 0));
	mul(hs_cx, hotspot[%1].myframe, 120);
	txtadd(hotspot[%1].crop, get(hs_cx), '|0|120|250');

	tween(hotspot[%1].myframe_timer, 1.0, 0.03, linear, hotspot_sprite_anim(%1) );
);

if(loaded,
	set(oy, 30);
	set(alpha, 0.0);
	set(scale, 0.15);

	tween(oy|alpha|scale, 0|1.0|0.25, 0.6, easeOutQuad,
		tween(oy|alpha|scale, -40|0.0|0.2, 0.6, easeInQuad,
			hotspot_pro_anim();
		);
	);
);

tween(scale, 0.17, 1.0, easeInOutSine,
	tween(scale, 0.13, 1.0, easeInOutSine, panorama_hotspot_bounce() )
);

if(caller.linkedscene,
	copy(hs_linkedscene, caller.linkedscene);
	if(caller.linkedscene_lookat, txtsplit(caller.linkedscene_lookat, ',', hs_lookat_h, hs_lookat_v, hs_lookat_fov); );
	set(caller.enabled, false);
	skin_hidetooltips();
	hide_custom_tooltip();
	tween(caller.depth|caller.alpha|caller.oy|caller.rx, 4000|0.0|-50|-60, 0.5, default,
		skin_loadscene(get(hs_linkedscene), ZOOMBLEND(2.0, 2.0, easeInOutSine));
		if(hs_lookat_h !== null, skin_lookat(get(hs_lookat_h), get(hs_lookat_v), get(hs_lookat_fov)); );
		skin_updatescroll();
	);
);

txtadd(glow_name, get(name), '_glow');
addhotspot(get(glow_name));
set(hotspot[get(glow_name)].url, 'core/assets/glow_base.svg');
set(hotspot[get(glow_name)].edge, center);
set(hotspot[get(glow_name)].distorted, true);
set(hotspot[get(glow_name)].rx, 75);
set(hotspot[get(glow_name)].alpha, 1.0);
copy(hotspot[get(glow_name)].ath, ath);
copy(hotspot[get(glow_name)].atv, atv);
set(hotspot[get(glow_name)].enabled, false);


glow_pulse(get(glow_name));

tween(hotspot[%1].scale, 0.45, 1.5, easeInOutSine,
	tween(hotspot[%1].scale, 0.3, 1.5, easeInOutSine, glow_pulse(%1) )
);

tween(oy, -10, 1.5, easeInOutSine,
	tween(oy, -5, 1.5, easeInOutSine, flyup_hotspot_hover() )
);

tween(scale, 0.15, 1.0, easeInOutSine,
	tween(scale, 0.25, 1.0, easeInOutSine, info_hotspot_pulse() )
);

if(custom_title,
	set(layer[custom_tooltip].visible, true);
	set(layer[custom_tooltip_text].html, get(custom_title));

	if(custom_thumb,
		set(layer[custom_tooltip_thumb].url, get(custom_thumb));
		set(layer[custom_tooltip_thumb].visible, true);
		set(layer[custom_tooltip].height, 125);
		set(layer[custom_tooltip_text].y, 45);
	,
		set(layer[custom_tooltip_thumb].visible, false);
		set(layer[custom_tooltip].height, 35);
		set(layer[custom_tooltip_text].y, 0);
	);


	asyncloop(layer[custom_tooltip].visible,
		set(layer[custom_tooltip].x, get(mouse.x));
		calc(layer[custom_tooltip].y, mouse.y - 35);
	);

	tween(layer[custom_tooltip].alpha, 1.0, 0.15);
);

if(webvr.isenabled,
	set(vr_gaze.gazing, true);
	copy(vr_gaze.target_scene, caller.linkedscene);
	tween(caller.scale, 0.50, 0.25, easeOutQuad);
	tween(caller.alpha, 1.0, 0.2);
	set(layer[vr_gaze_bar].visible, true);
	set(layer[vr_gaze_track].visible, true);
	set(layer[vr_gaze_bar].width, 0);
	tween(layer[vr_gaze_track].alpha, 1.0, 0.2);
	tween(layer[vr_gaze_bar].alpha, 1.0, 0.2);
	tween(layer[vr_gaze_bar].width, 160, 1.8, linear, vr_gaze_confirm());
);

set(vr_gaze.gazing, false);
tween(caller.scale, 0.38, 0.2);
tween(caller.alpha, 0.85, 0.2);
set(layer[vr_gaze_bar].width, 0);
tween(layer[vr_gaze_track].alpha, 0.0, 0.25, default, set(layer[vr_gaze_track].visible, false));
tween(layer[vr_gaze_bar].alpha, 0.0, 0.25, default, set(layer[vr_gaze_bar].visible, false));

if(vr_gaze.gazing,
	set(vr_gaze.gazing, false);
	tween(layer[vr_gaze_track].alpha, 0.0, 0.2, default, set(layer[vr_gaze_track].visible, false));
	tween(layer[vr_gaze_bar].alpha, 0.0, 0.2, default, set(layer[vr_gaze_bar].visible, false));
	skin_loadscene(get(vr_gaze.target_scene), ZOOMBLEND(2.0, 2.0, easeInOutSine));
);

if(webvr.isenabled,
	set(h, get(view.hlookat));
	set(v, 28);
	set(lv, 41);
	set(hotspot[vr_item_1].ath, calc(h - 80)); set(hotspot[vr_item_1].atv, get(v));
	set(hotspot[vr_label_1].ath, calc(h - 80)); set(hotspot[vr_label_1].atv, get(lv));
	set(hotspot[vr_item_2].ath, calc(h - 40)); set(hotspot[vr_item_2].atv, get(v));
	set(hotspot[vr_label_2].ath, calc(h - 40)); set(hotspot[vr_label_2].atv, get(lv));
	set(hotspot[vr_item_3].ath, get(h));        set(hotspot[vr_item_3].atv, get(v));
	set(hotspot[vr_label_3].ath, get(h));       set(hotspot[vr_label_3].atv, get(lv));
	set(hotspot[vr_item_4].ath, calc(h + 40)); set(hotspot[vr_item_4].atv, get(v));
	set(hotspot[vr_label_4].ath, calc(h + 40)); set(hotspot[vr_label_4].atv, get(lv));
	set(hotspot[vr_item_5].ath, calc(h + 80)); set(hotspot[vr_item_5].atv, get(v));
	set(hotspot[vr_label_5].ath, calc(h + 80)); set(hotspot[vr_label_5].atv, get(lv));
);

update_vr_menu_pos();
set(hotspot[vr_item_1].visible,true);  set(hotspot[vr_item_1].enabled,true);  tween(hotspot[vr_item_1].alpha, 0.85, 0.5);
set(hotspot[vr_item_2].visible,true);  set(hotspot[vr_item_2].enabled,true);  tween(hotspot[vr_item_2].alpha, 0.85, 0.5);
set(hotspot[vr_item_3].visible,true);  set(hotspot[vr_item_3].enabled,true);  tween(hotspot[vr_item_3].alpha, 0.85, 0.5);
set(hotspot[vr_item_4].visible,true);  set(hotspot[vr_item_4].enabled,true);  tween(hotspot[vr_item_4].alpha, 0.85, 0.5);
set(hotspot[vr_item_5].visible,true);  set(hotspot[vr_item_5].enabled,true);  tween(hotspot[vr_item_5].alpha, 0.85, 0.5);
set(hotspot[vr_label_1].visible,true); set(hotspot[vr_label_1].enabled,true); tween(hotspot[vr_label_1].alpha, 1.0, 0.5);
set(hotspot[vr_label_2].visible,true); set(hotspot[vr_label_2].enabled,true); tween(hotspot[vr_label_2].alpha, 1.0, 0.5);
set(hotspot[vr_label_3].visible,true); set(hotspot[vr_label_3].enabled,true); tween(hotspot[vr_label_3].alpha, 1.0, 0.5);
set(hotspot[vr_label_4].visible,true); set(hotspot[vr_label_4].enabled,true); tween(hotspot[vr_label_4].alpha, 1.0, 0.5);
set(hotspot[vr_label_5].visible,true); set(hotspot[vr_label_5].enabled,true); tween(hotspot[vr_label_5].alpha, 1.0, 0.5);

set(vr_gaze.gazing, false);
set(hotspot[vr_item_1].visible,false);  set(hotspot[vr_item_1].enabled,false);  set(hotspot[vr_item_1].alpha, 0.0);
set(hotspot[vr_item_2].visible,false);  set(hotspot[vr_item_2].enabled,false);  set(hotspot[vr_item_2].alpha, 0.0);
set(hotspot[vr_item_3].visible,false);  set(hotspot[vr_item_3].enabled,false);  set(hotspot[vr_item_3].alpha, 0.0);
set(hotspot[vr_item_4].visible,false);  set(hotspot[vr_item_4].enabled,false);  set(hotspot[vr_item_4].alpha, 0.0);
set(hotspot[vr_item_5].visible,false);  set(hotspot[vr_item_5].enabled,false);  set(hotspot[vr_item_5].alpha, 0.0);
set(hotspot[vr_label_1].visible,false); set(hotspot[vr_label_1].enabled,false); set(hotspot[vr_label_1].alpha, 0.0);
set(hotspot[vr_label_2].visible,false); set(hotspot[vr_label_2].enabled,false); set(hotspot[vr_label_2].alpha, 0.0);
set(hotspot[vr_label_3].visible,false); set(hotspot[vr_label_3].enabled,false); set(hotspot[vr_label_3].alpha, 0.0);
set(hotspot[vr_label_4].visible,false); set(hotspot[vr_label_4].enabled,false); set(hotspot[vr_label_4].alpha, 0.0);
set(hotspot[vr_label_5].visible,false); set(hotspot[vr_label_5].enabled,false); set(hotspot[vr_label_5].alpha, 0.0);

if(startscene === null OR !scene[get(startscene)],
	set(startscene, scene_toancanhconghai);
);
loadscene(get(startscene), null, MERGE);
if(startactions !== null, startactions() );
